-- PLAY SPOT — Script completo para InfinityFree
-- NÃO inclui CREATE DATABASE nem USE.
-- Importe via phpMyAdmin com o banco já selecionado.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `admin_config` (`id` INT AUTO_INCREMENT PRIMARY KEY, `senha_hash` VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `usuarios` (`id` INT AUTO_INCREMENT PRIMARY KEY, `nome` VARCHAR(100) NOT NULL, `email` VARCHAR(150) NOT NULL UNIQUE, `senha_hash` VARCHAR(255) NOT NULL, `bairro` VARCHAR(100), `cidade` VARCHAR(100) DEFAULT 'Contagem, MG', `avatar_iniciais` VARCHAR(5), `criado_em` DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `esportes` (`id` INT AUTO_INCREMENT PRIMARY KEY, `nome` VARCHAR(50) NOT NULL UNIQUE, `emoji` VARCHAR(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `usuario_esportes` (`usuario_id` INT NOT NULL, `esporte_id` INT NOT NULL, PRIMARY KEY (`usuario_id`,`esporte_id`), FOREIGN KEY (`usuario_id`) REFERENCES `usuarios`(`id`) ON DELETE CASCADE, FOREIGN KEY (`esporte_id`) REFERENCES `esportes`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `locais` (`id` INT AUTO_INCREMENT PRIMARY KEY, `nome` VARCHAR(150) NOT NULL, `endereco` VARCHAR(255), `bairro` VARCHAR(100), `cidade` VARCHAR(100) DEFAULT 'Contagem, MG', `latitude` DECIMAL(10,7), `longitude` DECIMAL(10,7), `emoji_capa` VARCHAR(20) DEFAULT '🏟', `aberto` TINYINT(1) DEFAULT 1, `criado_em` DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `local_esportes` (`local_id` INT NOT NULL, `esporte_id` INT NOT NULL, PRIMARY KEY (`local_id`,`esporte_id`), FOREIGN KEY (`local_id`) REFERENCES `locais`(`id`) ON DELETE CASCADE, FOREIGN KEY (`esporte_id`) REFERENCES `esportes`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `local_infraestrutura` (`id` INT AUTO_INCREMENT PRIMARY KEY, `local_id` INT NOT NULL, `descricao` VARCHAR(150) NOT NULL, `disponivel` TINYINT(1) DEFAULT 1, FOREIGN KEY (`local_id`) REFERENCES `locais`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `presencas` (`id` INT AUTO_INCREMENT PRIMARY KEY, `local_id` INT NOT NULL, `usuario_id` INT NOT NULL, `esporte_id` INT, `data_jogo` DATE NOT NULL, `horario` TIME, `qtd_pessoas` INT DEFAULT 1, `criado_em` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (`local_id`) REFERENCES `locais`(`id`) ON DELETE CASCADE, FOREIGN KEY (`usuario_id`) REFERENCES `usuarios`(`id`) ON DELETE CASCADE, FOREIGN KEY (`esporte_id`) REFERENCES `esportes`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;


